import pandas as pd

users = pd.DataFrame({"user_id": [1, 2, 3, 4, 5], "email": ["a@x.com", "b@x.com", None, "d@x.com", None], "age": [25, 130, 31, None, 40]})
RULES = [
    {"name": "email present", "severity": "critical", "ok": lambda d: d["email"].notna()},
    {"name": "age 0-120", "severity": "warning", "ok": lambda d: d["age"].isna() | d["age"].between(0, 120)},
]

def split(df, rules):
    keep = pd.Series(True, index=df.index)
    for rule in rules:
        if rule["severity"] == "critical":
            keep &= rule["ok"](df)
    return df[keep], df.loc[~keep, "user_id"].tolist()

def enforce(df, rules):
    failed = [r["name"] for r in rules if r["severity"] == "critical" and not r["ok"](df).all()]
    if failed:
        raise ValueError("critical rules failed: " + ", ".join(failed))
    return len(df)

clean, bad = split(users, RULES)
print(bad)
try:
    enforce(users, RULES)
except ValueError as exc:
    print("stopped:", exc)
print(enforce(clean, RULES))
